if ("undefined" == typeof MFRProductStickyBar) {
  class MFRProductStickyBar {
    constructor(index, element, options) {
      this.$index = index;
      this.$element = $(element);
      this.selectors = {
        stickyBarForm: ".product-sticky-bar__form",
        stickyBarCounter: "#sticky-counter",
        stickyBarPriceCounter: ".sticky-price",
        stickyBarQuantitySelector: ".quantity-selector",
        subscriptionWidget: "#shopify-block-AN21aOTB2L3p3RWNUd__recharge_subscriptions_subscription_widget_v2_jUW8zi",
        dressUpCharacter: ".dress-up__character",
      };
      this.options = options;
      this.basePrice = parseInt(this.$element.data("price")) || 0;
      this.subscriptionPrice = parseInt(this.$element.data("subscription-price")) || null;
      this.discountPercentage = parseFloat(this.$element.data("discount-percentage")) || null;
      // data-plan-discounts now carries per-plan { d: discountDecimal, q: planQuantity }
      // for Recharge quantity-upsell plans. The legacy shape (number) is still supported
      // for backwards compatibility with any non-migrated product.
      this.planConfig = JSON.parse(this.$element.attr("data-plan-discounts") || "{}");
      this.states = {
        currentProductQty: 1,
        currentProductPrice: this.subscriptionPrice || this.basePrice,
        currentTotalPrice: 0,
      };
      this.init();
    }

    init() {
      this.$stickyBarForm = this.$element.find(this.selectors.stickyBarForm).find("form");
      this.$stickyBarCounter = this.$element.find(this.selectors.stickyBarCounter);
      this.$stickyBarPriceCounter = this.$element.find(this.selectors.stickyBarPriceCounter);
      this.$quantitySelector = this.$element.find(this.selectors.stickyBarQuantitySelector);

      // Set initial price immediately — Liquid always renders full price by default
      this.$stickyBarPriceCounter.text(this.formatMoney(this.states.currentProductPrice));

      this.$quantitySelector.on("mfr:quantity-changed", this.ProductStickyCounter.bind(this));
      this.$stickyBarForm.on("submit", this.ProductStickyFormSubmit.bind(this));

      this.setupRechargeWidget();
      this.setupVariantListener();
      this.initVisibilityObserver();
    }

    initVisibilityObserver() {
      const widgetEl =
        document.querySelector(this.selectors.subscriptionWidget) ||
        document.querySelector("recharge-subscription-widget") ||
        document.querySelector(".rc-widget") ||
        document.querySelector(".subscription-selector") ||
        document.querySelector("form.product-top__form:not(.product-sticky-bar *)");

      if (!widgetEl) {
        console.warn("[Sticky Bar] Visibility target not found on this page! The bar will not show.");
        return;
      }

      const observer = new IntersectionObserver((entries) => {
        const isWidgetVisible = entries[0].isIntersecting;
        const showBar = !isWidgetVisible;
        this.$element.toggleClass("is-active", showBar);
        this.updateDressUpCharacter(showBar);
      }, { threshold: 0 });

      observer.observe(widgetEl);
    }

    updateDressUpCharacter(stickyVisible) {
      document.body.classList.toggle("sticky-atc-active", stickyVisible);
    }

    setupVariantListener() {
      const productForm = document.querySelector(
        "form.product-top__form:not(.product-sticky-bar *)"
      );
      if (!productForm) return;

      // Watch the variantSelectors container — section rendering replaces its
      // innerHTML after the fetch completes, at which point the newly checked
      // radio is in the fresh DOM with the correct data-price. The replaced
      // DOM also brings a fresh data-plan-discounts attribute on the sticky
      // bar's product node when the section is re-rendered, so re-parse it.
      const variantSelectors = productForm.querySelector('[x-ref="variantSelectors"]');
      if (variantSelectors) {
        const obs = new MutationObserver(() => {
          const checkedRadio = variantSelectors.querySelector('input[type="radio"][data-variant-id]:checked');
          if (!checkedRadio) return;

          // Sync variant ID to sticky bar form
          const newVariantId = checkedRadio.dataset.variantId;
          if (newVariantId) {
            this.$stickyBarForm.find('input[name="id"]').val(newVariantId);
          }

          // Re-parse the per-plan config in case allocations differ per variant
          this.planConfig = JSON.parse(this.$element.attr("data-plan-discounts") || "{}");

          const newBasePrice = parseInt(checkedRadio.dataset.price);
          if (newBasePrice && newBasePrice !== this.basePrice) {
            this.basePrice = newBasePrice;
            if (this.discountPercentage) {
              this.subscriptionPrice = Math.round(newBasePrice * (1 - this.discountPercentage / 100));
            }
          }
          this.readSellingPlanFromForm();
        });
        obs.observe(variantSelectors, { childList: true });
      }

      // Fallback for standard variant selectors using mfr:changed
      $(document).on("mfr:changed", (_e, data) => {
        if (!data || data.price == null) return;
        const newBasePrice = Math.round(parseFloat(data.price) * 100);
        this.basePrice = newBasePrice;
        if (this.discountRatio) {
          this.subscriptionPrice = Math.round(newBasePrice * this.discountRatio);
        }
        this.readSellingPlanFromForm();
      });
    }

    setupRechargeWidget() {
      // Recharge renders a Shadow DOM web component — change events don't escape it.
      // Instead we watch the selling_plan input Recharge injects into the product form.
      // Empty value = one-time purchase. Filled value = subscription selling plan ID.

      const rechargeWidget = document.querySelector("recharge-subscription-widget");
      if (rechargeWidget) {
        // Fallback: also read state after any click in the widget
        rechargeWidget.addEventListener("click", () => {
          setTimeout(() => this.readSellingPlanFromForm(), 50);
        });
      }

      // Recharge injects the selling_plan input after our JS runs — watch for it to appear
      const productForm = document.querySelector(
        "form.product-top__form:not(.product-sticky-bar *)"
      );
      if (!productForm) return;

      const existing = productForm.querySelector('input[name="selling_plan"]');
      if (existing) {
        this.observeSellingPlanInput(existing);
      } else {
        const formObserver = new MutationObserver(() => {
          const input = productForm.querySelector('input[name="selling_plan"]');
          if (input) {
            formObserver.disconnect();
            this.observeSellingPlanInput(input);
          }
        });
        formObserver.observe(productForm, { childList: true, subtree: true });
      }
    }

    observeSellingPlanInput(input) {
      const observer = new MutationObserver(() => this.readSellingPlanFromForm());
      observer.observe(input, { attributes: true, attributeFilter: ["disabled", "value"] });
    }

    readSellingPlanFromForm() {
      const productForm = document.querySelector(
        "form.product-top__form:not(.product-sticky-bar *)"
      );
      if (!productForm) return;
      const sellingPlan = productForm.querySelector('input[name="selling_plan"]');
      const isSubscription = sellingPlan && !sellingPlan.disabled && sellingPlan.value;
      let newPrice;
      let newPlanQty = 1;
      if (isSubscription) {
        const planId = sellingPlan.value;
        const cfg = this.planConfig[planId];
        // Support both new shape { d, q } and legacy shape (raw number)
        const discountDecimal = (cfg && typeof cfg === "object") ? cfg.d : cfg;
        const planQuantity = (cfg && typeof cfg === "object" && cfg.q) ? cfg.q : 1;
        if (discountDecimal != null) {
          newPrice = Math.round(this.basePrice * planQuantity * (1 - discountDecimal));
          newPlanQty = planQuantity;
        } else {
          newPrice = this.subscriptionPrice || this.basePrice;
        }
      } else {
        newPrice = this.basePrice;
      }
      this.currentPlanQuantity = newPlanQty;
      // Toggle class so CSS can hide the qty stepper while a quantity-upsell
      // subscription is selected — avoids "2 × 2 bottles" ambiguity. Pin
      // the displayed qty to 1 so currentProductPrice (already multiplied by
      // planQuantity) is what shows.
      this.$element.toggleClass("sticky-bar--subscription-active", isSubscription);
      if (isSubscription) {
        this.states.currentProductQty = 1;
        const $qtyInput = this.$quantitySelector.find(".quantity-selector__input");
        if ($qtyInput.length) $qtyInput.val(1);
      }
      this.updatePrice(newPrice);
    }

    updatePrice(price) {
      if (price === this.states.currentProductPrice) return;
      this.states.currentProductPrice = price;
      this.states.currentTotalPrice = price * this.states.currentProductQty;
      this.$stickyBarPriceCounter.text(this.formatMoney(this.states.currentTotalPrice));
    }

    formatMoney(cents) {
      return "$" + (cents / 100).toFixed(2);
    }

    ProductStickyFormSubmit() {
      const productForm = document.querySelector(
        "form.product-top__form:not(.product-sticky-bar *)"
      );
      if (productForm) {
        const sellingPlan = productForm.querySelector('input[name="selling_plan"]');
        const isSubscription = sellingPlan && !sellingPlan.disabled && sellingPlan.value;
        const stickySellingPlan = this.$stickyBarForm.find('input[name="selling_plan"]');
        const stickyQuantity = this.$stickyBarForm.find('input[name="quantity"]');
        if (isSubscription) {
          stickySellingPlan.val(sellingPlan.value).prop("disabled", false);
          // Mirror plan quantity onto the sticky form so /cart/add.js receives the
          // correct line-item qty (e.g. 2 for a "60 Day Supply" qty-upsell plan).
          // Falls back to the main form's quantity input if the plan isn't in our
          // config map (e.g. legacy non-upsell plan).
          const cfg = this.planConfig[sellingPlan.value];
          let qty = 1;
          if (cfg && typeof cfg === "object" && cfg.q) {
            qty = cfg.q;
          } else {
            const mainQty = productForm.querySelector('input[name="quantity"]');
            if (mainQty && mainQty.value) qty = parseInt(mainQty.value) || 1;
          }
          stickyQuantity.val(qty);
        } else {
          stickySellingPlan.val("").prop("disabled", true);
          // Mirror the user-selected one-time quantity (default 1)
          const mainQty = productForm.querySelector('input[name="quantity"]');
          stickyQuantity.val(mainQty && mainQty.value ? parseInt(mainQty.value) || 1 : 1);
        }
      }
      $(document).trigger("mfr:add-to-cart");
    }

    ProductStickyCounter() {
      this.states.currentProductQty = parseInt(
        this.$quantitySelector.find(".quantity-selector__input").val()
      );
      this.states.currentTotalPrice =
        this.states.currentProductPrice * this.states.currentProductQty;
      this.$stickyBarPriceCounter.text(this.formatMoney(this.states.currentTotalPrice));
    }
  }

  window.MFRProductStickyBar = MFRProductStickyBar;

  onReady(() => {
    $(".product-sticky-bar").each((index, element) => {
      new MFRProductStickyBar(index, element, {});
    });
  });
}
